(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20 + Math.sin(x*0.013+t*0.22)*15;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.3)*10 + Math.cos(my*0.02+t*0.25)*8;
  const w2y = Math.cos(my*0.025+t*0.28)*10 + Math.sin(mx*0.022-t*0.32)*8;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.63],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.26],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.88],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,2.51],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,3.14],
    [80+Math.sin(t*0.45+3)*110,40+Math.cos(t*0.65+2)*60,0.11,2.1,3.77],
    [400+Math.cos(t*0.55+1)*70,200+Math.sin(t*0.75+4)*50,0.05,2.8,4.4],
    [200+Math.sin(t*0.25+6)*130,220+Math.cos(t*0.45+3)*70,0.13,1.3,5.03],
    [300+Math.cos(t*0.7+2)*90,100+Math.sin(t*0.5+5)*80,0.075,2.4,5.65]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    hrm+=Math.cos(d*f*1.3-t*sp*0.8+ph*1.2)*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,hr=hrm/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08-sy*0.06+t*1.5)*Math.cos(sx*0.05+sy*0.09-t*0.7)*0.3;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5),sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.07-ang*2+t*0.8)*Math.cos(dist*0.03+ang*5-t*1.8);
  const spiral=(sp1+sp2)*0.3+sp3*0.2;
  const moire=Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx*0.14+sy*0.14)+t*0.5)*0.5;
  const raw=act-inh*0.6+bg*0.25+spiral+hr*0.3+moire*0.1;
  const r1=Math.tanh(raw*2.0);
  const r2=Math.tanh((r1+Math.sin(r1*3.14)*0.3+spiral*0.2)*1.8);
  const reaction=Math.tanh((r2+r1*0.3)*1.5);
  const c1=Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const c2=Math.sin(sx*0.22+1.5)*Math.sin(sy*0.22-0.8);
  const cell=Math.tanh((c1+c2*0.5+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const blend=reaction*0.7+cell*0.3,v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[10,45,85],[12,85,108],[18,140,120],[65,170,100],
    [180,195,65],[220,175,50],[225,130,55],[210,80,65],[175,50,75],
    [120,30,75],[65,18,58],[30,14,52],[5,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.08:1.0;
  const breathe=1.0+Math.sin(t*0.4)*0.05;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*breathe)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*breathe)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*breathe)|0
  ];
}
